from torch.utils.cpp_extension import load_inline

# Optimized CUDA kernel using warp-level matrix multiplication
cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define WARP_SIZE 32

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Warp-level matrix multiplication
    int warp_id = threadIdx.x / WARP_SIZE;
    int lane_id = threadIdx.x % WARP_SIZE;

    int warp_row = (blockIdx.y * TILE_SIZE) + warp_id;
    int warp_col = (blockIdx.x * TILE_SIZE) + lane_id;

    float sum = 0.0f;

    for (int k = 0; k < N; k++) {
        float a_val = 0.0f;
        float b_val = 0.0f;

        if (warp_row < N && k < N) {
            a_val = A[warp_row * N + k];
        }

        if (k < N && warp_col < N) {
            b_val = B[k * N + warp_col];
        }

        // Broadcast a_val to all threads in warp
        float a_shuffled = __shfl_sync(0xffffffff, a_val, lane_id);

        // Compute partial sum
        sum += a_shuffled * b_val;
    }

    // Write result
    if (warp_row < N && warp_col < N) {
        C[warp_row * N + warp_col] = sum;
    }
}

torch::Tensor matmul_forward_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    dim3 threadsPerBlock(1024);  // 32 warps per block
    dim3 numBlocks((N + TILE_SIZE - 1) / TILE_SIZE, 
